mapper.update:
UPDATE kit_job_log
SET
    handle_time = #{handleTime},
    handle_code = #{handleCode},
    handle_msg = #{handleMsg}
WHERE id = #{id}

mapper.select:
SELECT id FROM kit_job_log


        AND job_group = #{jobGroup}


        AND job_id = #{jobId}


        AND trigger_time  <=  #{clearBeforeTime}


        AND id NOT IN (
            SELECT id FROM (
                SELECT id FROM kit_job_log AS t


                        AND t.job_group = #{jobGroup}


                        AND t.job_id = #{jobId}


                ORDER BY t.trigger_time DESC
                LIMIT 0, #{clearBeforeNum}
            ) t1
        )


ORDER BY id ASC
LIMIT #{pagesize}

SELECT id FROM kit_job_log


        AND job_group = #{jobGroup}


        AND job_id = #{jobId}


        AND trigger_time  <=  #{clearBeforeTime}


        AND id NOT IN (
            SELECT id FROM (
                SELECT id FROM kit_job_log AS t


                        AND t.job_group = #{jobGroup}


                        AND t.job_id = #{jobId}


                ORDER BY t.trigger_time DESC
                LIMIT #{clearBeforeNum} OFFSET 0
            ) t1
        )


ORDER BY id ASC
LIMIT #{pagesize}

